CALLS = [
    {"name": "edit", "arguments": {"path": "src/lib.rs", "range": "1km-3wi", "new": "pub fn answer(command: &str) -> Option<i32> {\n    let command = command.strip_prefix(\"What is \")?.strip_suffix('?')?;\n    let tokens: Vec<&str> = command.split_whitespace().collect();\n    let mut i = 0;\n    let mut value = tokens.get(i)?.parse::<i32>().ok()?;\n    i += 1;\n    while i < tokens.len() {\n        let op = match tokens[i] {\n            \"plus\" => { i += 1; \"+\" }\n            \"minus\" => { i += 1; \"-\" }\n            \"multiplied\" | \"divided\" => {\n                let op = if tokens[i] == \"multiplied\" { \"*\" } else { \"/\" };\n                if tokens.get(i + 1)? != &\"by\" { return None; }\n                i += 2; op\n            }\n            \"raised\" if cfg!(feature = \"exponentials\") => {\n                if tokens.get(i + 1)? != &\"to\" || tokens.get(i + 2)? != &\"the\" { return None; }\n                let power = *tokens.get(i + 3)?;\n                let exp = match power { \"2nd\" => 2, \"3rd\" => 3, _ => return None };\n                if tokens.get(i + 4)? != &\"power\" { return None; }\n                i += 5; value = value.checked_pow(exp)?; continue;\n            }\n            _ => return None,\n        };\n        let rhs = tokens.get(i)?.parse::<i32>().ok()?;\n        i += 1;\n        value = match op {\n            \"+\" => value.checked_add(rhs)?,\n            \"-\" => value.checked_sub(rhs)?,\n            \"*\" => value.checked_mul(rhs)?,\n            \"/\" if rhs != 0 => value.checked_div(rhs)?,\n            _ => return None,\n        };\n    }\n    Some(value)\n}\n"}},
    {"name": "shell", "arguments": {"cmd": "cargo test --offline --features exponentials", "timeout": 120}},
]
